import pytest
from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

class Item(BaseModel):
    name: str
    age: Optional[int] = None

@app.post("/items/")
async def create_item(item: Item = Form(...)):
    return item

client = TestClient(app)

def test_empty_string_interpreted_as_none():
    # Sending name="test" and age=""
    # age is Optional[int] = None. 
    # The empty string should be interpreted as missing/None.
    # If the bug exists, the empty string "" will be passed to Pydantic,
    # which will fail to validate "" as an int.
    response = client.post(
        "/items/",
        data={"name": "test", "age": ""}
    )
    assert response.status_code == 200
    assert response.json() == {"name": "test", "age": None}

def test_provided_value_works():
    response = client.post(
        "/items/",
        data={"name": "test", "age": "25"}
    )
    assert response.status_code == 200
    assert response.json() == {"name": "test", "age": 25}

def test_missing_value_works():
    response = client.post(
        "/items/",
        data={"name": "test"}
    )
    assert response.status_code == 200
    assert response.json() == {"name": "test", "age": None}

